        /*
         * PRODUCT IMAGE FILE SETUP
         * ---------------------------------------------------------------
         * Keep a folder named `product-images` beside this HTML file.
         * Set the filename/base-name in PRODUCT_IMAGES above.
         * Example: PRODUCT_IMAGES['fn-1'] = 'fn-1.jpg';
         * Put the image at: product-images/fn-1.jpg
         * The website will load it automatically after deployment.
         * If no extension is written, .jpg/.jpeg/.png/.webp/.avif are tried.
         */
        const PRODUCT_IMAGE_FOLDER = "product-images/";
        const PRODUCT_IMAGE_EXTENSIONS = [".webp", ".jpg", ".jpeg", ".png", ".avif"];

        function getEmbeddedProductImage(product) {
            if (!product || !product.id) return "";
            if (Array.isArray(product.images) && product.images.length > 0) return product.images[0];
            const configured = PRODUCT_IMAGES[product.id];
            if (typeof configured !== "string" || !configured.trim()) return "";
            const fileName = configured.trim();
            if (/^(data:|https?:|blob:|\.\.\/|\/)/i.test(fileName)) return fileName;
            if (/\.(webp|jpe?g|png|avif)$/i.test(fileName)) return PRODUCT_IMAGE_FOLDER + fileName;
            return PRODUCT_IMAGE_FOLDER + fileName + ".webp";
        }

        function tryNextProductImage(img) {
            if (!img) return;
            const base = img.dataset.imageBase || "";
            let index = parseInt(img.dataset.extIndex || "0", 10);
            if (!base || index >= PRODUCT_IMAGE_EXTENSIONS.length) {
                img.style.display = "none";
                const parent = img.parentElement;
                if (parent && !parent.querySelector('.product-image-fallback')) {
                    parent.classList.add('bg-teal-50');
                    const span = document.createElement('span');
                    span.className = 'product-image-fallback text-4xl';
                    span.textContent = img.dataset.emoji || '💡';
                    parent.appendChild(span);
                }
                return;
            }
            img.dataset.extIndex = String(index + 1);
            img.src = PRODUCT_IMAGE_FOLDER + base + PRODUCT_IMAGE_EXTENSIONS[index];
        }

        if (typeof window !== "undefined") {
            window.originalProducts = originalProducts;
            window.PRODUCT_IMAGES = PRODUCT_IMAGES;
            window.getEmbeddedProductImage = getEmbeddedProductImage;
            window.tryNextProductImage = tryNextProductImage;
        }